sys_script_include.script:
var FleetVehicleStatus = Class.create();
FleetVehicleStatus.prototype = {
    // FLEET-33: vehicle status is derived from maintenance, custody and active trips (never edited by hand except RETIRED)
    VEH: 'x_1850693_enterp_0_vehicle',

    initialize: function() {},

    /** Status the vehicle should have, evaluated in the FLEET-33 order. */
    compute: function(vehicle) {
        var id = vehicle.getUniqueValue();
        if (vehicle.getValue('status') == 'RETIRED') {
            return 'RETIRED';
        }
        var m = new GlideRecord('x_1850693_enterp_0_maintenance');
        m.addEncodedQuery('vehicle=' + id + '^maintenance_state=IN_PROGRESS^NQvehicle=' + id + '^maintenance_type=CORRECTIVE^urgency_level=HIGH^active=true');
        m.setLimit(1);
        m.query();
        if (m.hasNext()) {
            return 'MAINTENANCE'; // D-15
        }
        if (!vehicle.assigned_driver.nil()) {
            return 'IN_CUSTODY';
        }
        var r = new GlideRecord('x_1850693_enterp_0_reservation');
        r.addQuery('assigned_vehicle', id);
        r.addQuery('reservation_state', 'ACTIVE');
        r.setLimit(1);
        r.query();
        if (r.hasNext()) {
            return 'RESERVED';
        }
        return 'AVAILABLE';
    },

    /** Recomputes and saves the status of one vehicle. Returns the status. */
    sync: function(vehicleId) {
        if (!vehicleId) {
            return '';
        }
        var v = new GlideRecord(this.VEH);
        if (!v.get(vehicleId)) {
            return '';
        }
        var status = this.compute(v);
        if (v.getValue('status') != status) {
            v.setValue('status', status);
            v.setWorkflow(false); // status only; vehicle data rules are not re-run
            v.update();
        }
        return status;
    },

    type: 'FleetVehicleStatus'
};
FleetVehicleStatus.sync = function(vehicleId) {
    return new FleetVehicleStatus().sync(vehicleId);
};
